import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import 'bootstrap/dist/css/bootstrap.min.css';
import './App.css';

// Components
import Navigation from './components/Navigation';
import Footer from './components/Footer';

// Pages
import Dashboard from './pages/Dashboard';

// Placeholder components for routes
const PortfolioList = () => <div className="container mt-4"><h1>Portfolios</h1><p>This page will display a list of your portfolios.</p></div>;
const PortfolioDetail = () => <div className="container mt-4"><h1>Portfolio Details</h1><p>This page will show detailed information about a specific portfolio.</p></div>;
const ImportPortfolio = () => <div className="container mt-4"><h1>Import Portfolio</h1><p>This page will allow you to import portfolio data from various sources.</p></div>;
const PerformanceAttribution = () => <div className="container mt-4"><h1>Performance Attribution</h1><p>This page will show detailed performance attribution analysis.</p></div>;
const TaxAnalysis = () => <div className="container mt-4"><h1>Tax Analysis</h1><p>This page will provide tax analysis for your investments.</p></div>;
const CashFlowProjections = () => <div className="container mt-4"><h1>Cash Flow Projections</h1><p>This page will show projected cash flows from your investments.</p></div>;

function App() {
  return (
    <Router>
      <div className="d-flex flex-column min-vh-100">
        <Navigation />
        <main className="flex-grow-1">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/portfolios" element={<PortfolioList />} />
            <Route path="/portfolios/:id" element={<PortfolioDetail />} />
            <Route path="/import" element={<ImportPortfolio />} />
            <Route path="/performance" element={<PerformanceAttribution />} />
            <Route path="/tax" element={<TaxAnalysis />} />
            <Route path="/cashflow" element={<CashFlowProjections />} />
          </Routes>
        </main>
        <Footer />
      </div>
    </Router>
  );
}

export default App;
